"""Shift call-out helper: picks the next available cook for an open shift."""
def fill_shift(roster, shift_hours, unavailable):
    # roster: list of (name, hours_this_week, max_hours)
    candidates = [(n, h) for n, h, mx in roster if n not in unavailable and h + shift_hours <= mx]
    candidates.sort(key=lambda x: x[1])  # least hours first
    return candidates[0][0] if candidates else None

def send_request(roster, shift_hours, unavailable):
    # Returns a per-person status dict shown right after the call-out is sent.
    # statuses: "sent" (request went out), "unavailable" (marked out), "not eligible" (over hours)
    status = {}
    for n, h, mx in roster:
        if n in unavailable:
            status[n] = "unavailable"
        elif h + shift_hours > mx:
            status[n] = "not eligible (over hours)"
        else:
            status[n] = "sent"
    return status

def render_status(status):
    lines = [f"{name}: {state}" for name, state in status.items()]
    return "\n".join(lines)

if __name__ == "__main__":
    roster = [("Ana", 32, 40), ("Luis", 24, 35), ("Kim", 38, 40)]
    print(fill_shift(roster, 8, unavailable={"Luis"}))  # -> Ana
    print(render_status(send_request(roster, 8, unavailable={"Luis"})))

