# Reply states from parents (week 17): yes/ok = confirmed, no/can't = declined,
# conditional reply ("can do 4 to close") = maybe, no reply yet = sent/seen.
def classify_reply(text):
    t = text.strip().lower()
    if not t or t in ("…", "..."):
        return "seen"
    if t in ("yes", "ok", "okay", "yep", "yup"):
        return "confirmed"
    if t.startswith("no") or t.startswith("can't") or t.startswith("cant"):
        return "declined"
    return "maybe"

def update_status(status, replies):
    # replies: dict of name -> reply text; only updates people who were "sent"
    for name, text in replies.items():
        if status.get(name) in ("sent", "seen", "maybe"):
            status[name] = classify_reply(text)
    return status
